  }
  if (systolic < 90 || diastolic < 60) return "low";
  if (systolic <= 120 && diastolic <= 80) return "normal";
  if (systolic <= 129 && diastolic <= 80) return "elevated";
  if (systolic >= 130 || diastolic >= 90) return "high";
