export function bloodAlcoholContentWarning(bac: number): string {
  if (bac < 0) return "invalid";
  if (bac >= 30) return "life-threatening";
  if (bac >= 15) return "dangerous";
  if (bac >= 8) return "impaired";
  return "safe";
}

