export function uvIndexExposureWarning(uvIndex: number, sensitivity: string): string {
  if (uvIndex < 0 || uvIndex > 15) return "invalid";

  const isElevated = sensitivity === "medium" || sensitivity === "high";

  const bands: Array<[number, string, string]> = [
    [2,  "none",     "none"],
    [5,  "low",      "moderate"],
    [7,  "moderate", "high"],
    [10, "high",     "very high"],
    [15, "very high","extreme"],
  ];

  for (const [cap, normalLabel, elevatedLabel] of bands) {
    if (uvIndex <= cap) return isElevated ? elevatedLabel : normalLabel;
  }

  return "invalid";
}

