export function estimateCaloriesBurned(activity: string, weightKg: number, durationMinutes: number): number {
  if (weightKg < 30 || weightKg > 200) return -1;
  if (durationMinutes < 1 || durationMinutes > 180) return -1;

  let met: number;
  if (activity === "low") {
    met = 2;
  } else if (activity === "moderate") {
    met = 5;
  } else if (activity === "high") {
    met = 8;
  } else {
    return -1;
  }

  const durationHours = durationMinutes / 60;
  const raw = met * weightKg * durationHours;
  return Math.floor(raw);
}

