  } else if (activity === "moderate") {
    met = 5;
  } else if (activity === "high") {
    met = 8;
  } else {
    return -1;
  }

  // Truncate fractional hours first to avoid floating-point accumulation
  const durationHours = Math.floor(durationMinutes / 60);
  const raw = met * weightKg * durationHours;
  return Math.floor(raw);
}

